(function(){'use strict';
const KEY='nawaf-hq-v5';
let currentTaskId='';
function read(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{return {}}}
function write(s){localStorage.setItem(KEY,JSON.stringify(s));window.dispatchEvent(new CustomEvent('nawaf:state-updated',{detail:{reason:'task-deleted'}}));window.dispatchEvent(new CustomEvent('nawaf:activity-updated'))}
function removeTaskFromState(state,id){if(!state||typeof state!=='object')state={};const task=(state.tasks||[]).find(t=>String(t.id)===String(id));state.tasks=Array.isArray(state.tasks)?state.tasks.filter(t=>String(t.id)!==String(id)):[];state.reports=Array.isArray(state.reports)?state.reports.filter(r=>String(r.sourceTaskId||'')!==String(id)):[];state.approvals=Array.isArray(state.approvals)?state.approvals.filter(a=>String(a.taskId||a.sourceTaskId||'')!==String(id)):[];state.secretaryBriefs=Array.isArray(state.secretaryBriefs)?state.secretaryBriefs.filter(b=>String(b.taskId||'')!==String(id)):[];if(Array.isArray(state.secretarySeen))state.secretarySeen=state.secretarySeen.filter(x=>!String(x).startsWith(String(id)+':'));if(task&&Array.isArray(state.employees)){const e=state.employees.find(x=>x.id===task.employeeId);if(e&&(e.task===task.title||e.task===task.details||['WORKING','RESEARCHING','REVIEWING','BLOCKED_BY_TOOL','WAITING_FOR_NAWAF','BLOCKED','PAUSED'].includes(e.status))){e.task='';e.status='READY';e.updatedAt=new Date().toISOString()}}state.updatedAt=new Date().toISOString();return state}
async function persistDelete(id){const r=await fetch('/api/state',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({deleteTaskId:id}),cache:'no-store'});const j=await r.json().catch(()=>({}));if(!r.ok||!j?.ok)throw new Error(j?.error||'TASK_DELETE_FAILED');if(j.state&&typeof j.state==='object')write(j.state);return true}
async function deleteTask(id){const s=read(),task=(s.tasks||[]).find(t=>String(t.id)===String(id));if(!task)return;if(!confirm(`حذف المهمة نهائيًا؟\n\n${task.title||'المهمة'}`))return;showToast('جاري حذف المهمة...');try{await persistDelete(id);document.querySelector('#v8-modal')?.classList.remove('show');window.NawafHQV8?.render?.();showToast('تم حذف المهمة نهائيًا')}catch(err){showToast('تعذر حذف المهمة من السحابة: '+String(err.message||err))}}
function showToast(text){let el=document.querySelector('.v8-toast');if(!el){el=document.createElement('div');el.className='v8-toast';document.body.appendChild(el)}el.textContent=text;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2600)}
function inject(){const modal=document.querySelector('#v8-modal.show'),actions=modal?.querySelector('.v8-modal-actions');if(!modal||!actions||!currentTaskId||actions.querySelector('[data-delete-task]'))return;const b=document.createElement('button');b.type='button';b.className='v8-btn';b.dataset.deleteTask=currentTaskId;b.textContent='🗑 حذف المهمة';b.style.borderColor='rgba(255,95,95,.35)';b.style.color='#ff9d9d';actions.prepend(b)}
document.addEventListener('click',e=>{const row=e.target.closest('[data-task]');if(row){currentTaskId=row.dataset.task||'';setTimeout(inject,0);return}const del=e.target.closest('[data-delete-task]');if(del){e.preventDefault();e.stopPropagation();deleteTask(del.dataset.deleteTask)}} ,true);
const obs=new MutationObserver(()=>setTimeout(inject,0));function boot(){obs.observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['class']})}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
window.NawafTaskDelete={deleteTask};
})();
